<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';

const props=defineProps<{view:string}>();
const campaigns=ref<any[]>([]), coupons=ref<any[]>([]), metrics=ref<any[]>([]), loading=ref(false), error=ref('');
async function api(method:string,url:string,data?:any){const token=document.querySelector<HTMLMetaElement>('meta[name=csrf-token]')?.content;const response=await fetch(url,{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest',...(token?{'X-CSRF-TOKEN':token}:{})},...(data?{body:JSON.stringify(data)}:{})});const payload=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(payload.message||'Request failed'),{response:{data:payload}});return payload}
const showCampaign=ref(false), showCoupon=ref(false), editing=ref<number|null>(null);
const campaign=reactive<any>({name:'',channel:'onsite',objective:'',description:'',status:'draft',budget:0,starts_at:'',ends_at:''});
const coupon=reactive<any>({code:'',name:'',discount_type:'percentage',discount_value:10,minimum_order:0,is_active:true,usage_limit:null,per_customer_limit:null,starts_at:'',ends_at:''});
const title=computed(()=>props.view==='coupons'?'Coupons & Offers':props.view==='campaigns'?'Campaign Management':'Marketing Overview');
async function load(){loading.value=true;error.value='';try{const [c,o,a]=await Promise.all([api('GET','/api/marketing/campaigns'),api('GET','/api/marketing/coupons'),api('GET','/api/marketing/analytics')]);campaigns.value=c.data?.data??[];coupons.value=o.data??[];metrics.value=a.data??[]}catch(e:any){error.value=e.response?.data?.message||'Unable to load marketing data.'}finally{loading.value=false}}
function newCampaign(){editing.value=null;Object.assign(campaign,{name:'',channel:'onsite',objective:'',description:'',status:'draft',budget:0,starts_at:'',ends_at:''});showCampaign.value=true}
function editCampaign(x:any){editing.value=x.id;Object.assign(campaign,{...x,starts_at:x.starts_at?.slice(0,16)||'',ends_at:x.ends_at?.slice(0,16)||''});showCampaign.value=true}
async function saveCampaign(){try{const url=editing.value?`/api/marketing/campaigns/${editing.value}`:'/api/marketing/campaigns';await api(editing.value?'PUT':'POST',url,campaign);showCampaign.value=false;await load()}catch(e:any){error.value=e.response?.data?.message||'Campaign could not be saved.'}}
async function deleteCampaign(x:any){if(confirm(`Delete campaign “${x.name}”?`)){await api('DELETE',`/api/marketing/campaigns/${x.id}`);await load()}}
function newCoupon(){Object.assign(coupon,{code:'',name:'',discount_type:'percentage',discount_value:10,minimum_order:0,is_active:true,usage_limit:null,per_customer_limit:null,starts_at:'',ends_at:''});editing.value=null;showCoupon.value=true}
function editCoupon(x:any){editing.value=x.id;Object.assign(coupon,{...x,starts_at:x.starts_at?.slice(0,16)||'',ends_at:x.ends_at?.slice(0,16)||''});showCoupon.value=true}
async function saveCoupon(){try{const url=editing.value?`/api/marketing/coupons/${editing.value}`:'/api/marketing/coupons';await api(editing.value?'PUT':'POST',url,coupon);showCoupon.value=false;await load()}catch(e:any){error.value=e.response?.data?.message||'Coupon could not be saved.'}}
async function deleteCoupon(x:any){if(confirm(`Delete coupon ${x.code}?`)){await api('DELETE',`/api/marketing/coupons/${x.id}`);await load()}}
onMounted(load);
</script>
<template><main class="p-6 space-y-5"><header class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-semibold tracking-widest text-emerald-600">GROWTH & CUSTOMER ENGAGEMENT</p><h1 class="text-2xl font-semibold">{{title}}</h1><p class="text-sm text-slate-500">Manage campaigns, offers and measurable marketing activity.</p></div><div class="flex gap-2"><button v-if="view!=='coupons'" class="rounded-lg bg-slate-900 px-4 py-2 text-white" @click="newCampaign">＋ New campaign</button><button v-if="view==='coupons'" class="rounded-lg bg-slate-900 px-4 py-2 text-white" @click="newCoupon">＋ New coupon</button></div></header><p v-if="error" class="rounded-lg bg-red-50 p-3 text-red-700">{{error}}</p><p v-if="loading" class="text-sm text-slate-500">Loading…</p><template v-if="view==='coupons'"><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Code</th><th>Name</th><th>Discount</th><th>Usage</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="x in coupons" :key="x.id" class="border-t"><td class="p-3 font-semibold">{{x.code}}</td><td>{{x.name}}</td><td>{{x.discount_value}} {{x.discount_type==='percentage'?'%':'৳'}}</td><td>{{x.used_count}} / {{x.usage_limit??'∞'}}</td><td>{{x.is_active?'Active':'Inactive'}}</td><td><button class="mr-3 text-blue-600" @click="editCoupon(x)">Edit</button><button class="text-red-600" @click="deleteCoupon(x)">Delete</button></td></tr></tbody></table></div></template><template v-else><section v-if="view==='overview'" class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><article v-for="m in [{l:'Campaigns',v:metrics.length},{l:'Impressions',v:metrics.reduce((n,x)=>n+Number(x.impressions_count||0),0)},{l:'Clicks',v:metrics.reduce((n,x)=>n+Number(x.clicks_count||0),0)},{l:'Conversions',v:metrics.reduce((n,x)=>n+Number(x.conversions_count||0),0)}]" class="rounded-xl border bg-white p-4"><p class="text-sm text-slate-500">{{m.l}}</p><strong class="text-2xl">{{m.v.toLocaleString()}}</strong></article></section><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Campaign</th><th>Channel</th><th>Status</th><th>Budget</th><th>Impressions</th><th>Clicks</th><th>Conversions</th><th>Actions</th></tr></thead><tbody><tr v-for="x in metrics" :key="x.id" class="border-t"><td class="p-3 font-medium">{{x.name}}</td><td>{{x.channel}}</td><td>{{x.status}}</td><td>৳{{Number(x.budget).toLocaleString()}}</td><td>{{x.impressions_count}}</td><td>{{x.clicks_count}}</td><td>{{x.conversions_count}}</td><td><button class="mr-3 text-blue-600" @click="editCampaign(x)">Edit</button><button class="text-red-600" @click="deleteCampaign(x)">Delete</button></td></tr><tr v-if="!metrics.length"><td colspan="8" class="p-8 text-center text-slate-500">No campaigns yet. Create your first campaign.</td></tr></tbody></table></div></template><div v-if="showCampaign" class="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4"><form class="w-full max-w-xl space-y-3 rounded-xl bg-white p-5" @submit.prevent="saveCampaign"><h2 class="text-lg font-semibold">{{editing?'Edit':'Create'}} campaign</h2><label class="block text-sm">Name<input v-model="campaign.name" required class="mt-1 w-full rounded border p-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Channel<select v-model="campaign.channel" class="mt-1 w-full rounded border p-2"><option v-for="x in ['onsite','email','sms','social','paid_ads','other']">{{x}}</option></select></label><label class="text-sm">Status<select v-model="campaign.status" class="mt-1 w-full rounded border p-2"><option v-for="x in ['draft','scheduled','active','paused','completed','archived']">{{x}}</option></select></label></div><label class="block text-sm">Objective<input v-model="campaign.objective" class="mt-1 w-full rounded border p-2"></label><label class="block text-sm">Description<textarea v-model="campaign.description" class="mt-1 w-full rounded border p-2"></textarea></label><label class="block text-sm">Budget (৳)<input v-model.number="campaign.budget" type="number" min="0" class="mt-1 w-full rounded border p-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Starts<input v-model="campaign.starts_at" type="datetime-local" class="mt-1 w-full rounded border p-2"></label><label class="text-sm">Ends<input v-model="campaign.ends_at" type="datetime-local" class="mt-1 w-full rounded border p-2"></label></div><footer class="flex justify-end gap-2"><button type="button" class="rounded border px-4 py-2" @click="showCampaign=false">Cancel</button><button class="rounded bg-slate-900 px-4 py-2 text-white">Save campaign</button></footer></form></div><div v-if="showCoupon" class="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4"><form class="w-full max-w-lg space-y-3 rounded-xl bg-white p-5" @submit.prevent="saveCoupon"><h2 class="text-lg font-semibold">{{editing?'Edit':'Create'}} coupon</h2><label class="block text-sm">Code<input v-model="coupon.code" required class="mt-1 w-full rounded border p-2"></label><label class="block text-sm">Name<input v-model="coupon.name" required class="mt-1 w-full rounded border p-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Type<select v-model="coupon.discount_type" class="mt-1 w-full rounded border p-2"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label class="text-sm">Value<input v-model.number="coupon.discount_value" type="number" min="0.01" step="0.01" class="mt-1 w-full rounded border p-2"></label></div><label class="block text-sm">Minimum order (৳)<input v-model.number="coupon.minimum_order" type="number" min="0" class="mt-1 w-full rounded border p-2"></label><label class="flex items-center gap-2 text-sm"><input v-model="coupon.is_active" type="checkbox"> Active</label><footer class="flex justify-end gap-2"><button type="button" class="rounded border px-4 py-2" @click="showCoupon=false">Cancel</button><button class="rounded bg-slate-900 px-4 py-2 text-white">Save coupon</button></footer></form></div></main></template>
